pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address firstNewOwner, address secondNewOwner) internal {
        try c.setOwner(firstNewOwner) {} catch { return; }
        bool secondCallSucceeded;
        try c.setOwner(secondNewOwner) returns (bool __r) { secondCallSucceeded = __r; } catch { return; }
        assertTrue(secondCallSucceeded == true);
    }

    function testFuzz_run(address firstNewOwner, address secondNewOwner) public {
        vm.assume(firstNewOwner.code.length == 0 && uint160(firstNewOwner) > 0xffff && firstNewOwner != address(this) && firstNewOwner != address(c) && firstNewOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && firstNewOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && firstNewOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && firstNewOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(secondNewOwner.code.length == 0 && uint160(secondNewOwner) > 0xffff && secondNewOwner != address(this) && secondNewOwner != address(c) && secondNewOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && secondNewOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && secondNewOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && secondNewOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(firstNewOwner, secondNewOwner);
    }

    receive() external payable {}
}
